const state = $getWorkflowStaticData('global');
state.groupTitle = state.groupTitle ?? 'PBG Discussion';
state.groupHref = state.groupHref ?? 'https://t.me/+Xpdv7ztBFFc1MGVh';
state.latestSequence = Number.isFinite(state.latestSequence) ? state.latestSequence : 0;
state.seenByStudent = state.seenByStudent && typeof state.seenByStudent === 'object' ? state.seenByStudent : {};
state.chatId = Number.isFinite(state.chatId) ? state.chatId : -1002059446209;
state.telegramOffset = Number.isFinite(state.telegramOffset) ? state.telegramOffset : 0;

const source = $('Prepare Telegram Poll').first().json;
const payload = $json;
if (!payload.ok || !Array.isArray(payload.result)) {
  throw new Error('Telegram getUpdates returned an invalid payload');
}

let matchedCount = 0;
for (const update of payload.result) {
  const updateId = typeof update.update_id === 'number' ? update.update_id : null;
  if (updateId !== null) {
    state.telegramOffset = Math.max(state.telegramOffset, updateId + 1);
  }

  const message = update.message ?? update.channel_post ?? update.edited_message ?? null;
  if (!message?.chat) {
    continue;
  }

  const chat = message.chat;
  const chatId = typeof chat.id === 'number' ? chat.id : null;
  const chatType = typeof chat.type === 'string' ? chat.type : '';
  const title = typeof chat.title === 'string' ? chat.title.trim() : '';
  const isGroupLike = chatType === 'group' || chatType === 'supergroup';
  const bootstrapMatch = state.chatId === null && isGroupLike && !message.from?.is_bot;
  const matchesKnownChat = chatId !== null && chatId === state.chatId;
  const isTargetChat = matchesKnownChat || bootstrapMatch;
  if (!isTargetChat) {
    continue;
  }

  if (state.chatId === null && chatId !== null) {
    state.chatId = chatId;
  }

  if (message.from?.is_bot) {
    continue;
  }

  state.latestSequence += 1;
  matchedCount += 1;
  state.lastMessageId = typeof message.message_id === 'number' ? message.message_id : state.lastMessageId ?? null;
  state.lastMessageDate = typeof message.date === 'number' ? message.date : state.lastMessageDate ?? null;
  state.lastPreview = typeof message.text === 'string' ? message.text.slice(0, 160) : null;
  state.lastChatTitle = title || state.lastChatTitle || null;
  state.lastChatType = chatType || state.lastChatType || null;
}

return [{
  json: {
    ok: true,
    source: source.source,
    matchedCount,
    latestSequence: state.latestSequence,
    chatId: state.chatId,
    offset: state.telegramOffset,
    lastMessageId: state.lastMessageId ?? null,
    lastChatTitle: state.lastChatTitle || null,
    lastChatType: state.lastChatType || null
  }
}];

const state = $getWorkflowStaticData('global');
state.groupTitle = state.groupTitle ?? 'PBG Discussion';
state.groupHref = state.groupHref ?? 'https://t.me/+Xpdv7ztBFFc1MGVh';
state.latestSequence = Number.isFinite(state.latestSequence) ? state.latestSequence : 0;
state.seenByStudent = state.seenByStudent && typeof state.seenByStudent === 'object' ? state.seenByStudent : {};

const query = $json.query ?? {};
const studentId = typeof query.studentId === 'string' ? query.studentId.trim() : '';
if (!studentId) {
  return [{ json: { label: state.groupTitle, href: state.groupHref, unreadCount: 0, error: 'missing_student_id' } }];
}

const seenMarker = Number.isFinite(state.seenByStudent[studentId]) ? state.seenByStudent[studentId] : 0;
const unreadCount = Math.max(state.latestSequence - seenMarker, 0);

return [{
  json: {
    label: state.groupTitle,
    href: state.groupHref,
    unreadCount
  }
}];

const state = $getWorkflowStaticData('global');
state.groupTitle = state.groupTitle ?? 'PBG Discussion';
state.groupHref = state.groupHref ?? 'https://t.me/+Xpdv7ztBFFc1MGVh';
state.latestSequence = Number.isFinite(state.latestSequence) ? state.latestSequence : 0;
state.seenByStudent = state.seenByStudent && typeof state.seenByStudent === 'object' ? state.seenByStudent : {};

const body = $json.body ?? {};
const studentId = typeof body.studentId === 'string' ? body.studentId.trim() : '';
if (!studentId) {
  return [{ json: { ok: true, unreadCount: state.latestSequence, error: 'missing_student_id' } }];
}

state.seenByStudent[studentId] = state.latestSequence;
return [{
  json: {
    ok: true,
    unreadCount: 0
  }
}];
